                "t_ledgerlet": "LedgerLet — Making Tax Digital pour les bailleurs britanniques",
                "t_voltedge": "VoltEdge — Plateforme d'intelligence énergétique pour l'entreprise",
                "t_voltscope": "VoltScope — Analyse et extraction des factures d'énergie au Royaume-Uni",
                "t_cliniq": "ClinIQ — Intelligence sur la performance des sites d'essais cliniques",
                "t_salaryaxis": "SalaryAxis — Plateforme d'intelligence salariale au Royaume-Uni",
                "t_mathadventure": "Math Adventure — Les maths pour les enfants",
                "t_searchwars": "SearchWars — Lequel est le plus recherché sur Google ?",
